export function normalizeHelpSearch(value: string): string {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLocaleLowerCase("fr-FR").replace(/[^a-z0-9]+/g, " ").trim();
}

export function searchHelpSections(query: string, sections: HelpSection[] = helpSections): HelpSection[] {
  const terms = normalizeHelpSearch(query).split(/\s+/).filter(Boolean);
  if (!terms.length) return sections;
  return sections.flatMap(section => {
    const context = `${section.title} ${section.description} ${section.keywords}`;
    const articles = section.articles.filter(item => {
      const text = normalizeHelpSearch([context, item.title, ...item.body, ...(item.steps ?? []), item.tip ?? ""].join(" "));
      return terms.every(term => text.includes(term));
    });
    return articles.length ? [{ ...section, articles }] : [];
  });
}
